using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Text;using VisibleCellsPaste;
// Only an explicitly owned Excel PID. Creates/closes its own unique regression workbook;
// preserves references to every previously open workbook and restores globals/selection.
class RegressionScope {
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 [STAThread]static int Main(string[] args){if(args.Length!=3)throw new ArgumentException("ownedPID outputDir uniqueFixtureFile");string root=Path.GetFullPath(Path.Combine(Environment.CurrentDirectory,"artifacts","visible-cells-paste"))+Path.DirectorySeparatorChar;string folder=Path.GetFullPath(args[1]),file=Path.GetFullPath(args[2]);Check(folder.StartsWith(root,StringComparison.OrdinalIgnoreCase)&&file.StartsWith(root,StringComparison.OrdinalIgnoreCase),"Owned artifact path required");Check(!File.Exists(file),"Fixture already exists");Directory.CreateDirectory(folder);Directory.CreateDirectory(Path.GetDirectoryName(file));dynamic app=ExcelProbe.Attach(Int32.Parse(args[0]));object originalBook=app.ActiveWorkbook,originalSheet=app.ActiveSheet,originalSelection=app.Selection;object events=app.EnableEvents,calc=app.Calculation,screen=app.ScreenUpdating,status=app.StatusBar,alerts=app.DisplayAlerts;var prior=new List<object>();var names=new List<string>();foreach(dynamic b in app.Workbooks){Check(((string)b.Name).StartsWith("VCP-",StringComparison.Ordinal),"All existing workbooks must be owned VCP fixtures");prior.Add((object)b);names.Add((string)b.FullName);}Check(prior.Count==3,"Expected root-owned three-workbook starting state");dynamic owned=null;int failed=0;try{owned=app.Workbooks.Add();owned.SaveAs(file,51);Console.WriteLine("Created unique owned regression workbook; existing_workbooks="+prior.Count);foreach(string test in new[]{"FunctionalTests","ExtendedTests","RemainingSafetyTests"}){owned.Activate();string output=Path.Combine(folder,test+".txt");string testArgs=args[0]+" \""+output+"\"";if(test=="FunctionalTests")testArgs+=" --synthetic-regression";if(test=="RemainingSafetyTests")testArgs+=" \""+Path.Combine(folder,"remaining-fixtures")+"\"";var start=new ProcessStartInfo(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,test+".exe"),testArgs){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=Environment.CurrentDirectory};Console.WriteLine("START "+test+" UTC="+DateTime.UtcNow.ToString("o"));using(var process=Process.Start(start)){var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();process.WaitForExit();File.WriteAllText(output+".console.txt",stdout.GetAwaiter().GetResult(),Encoding.UTF8);File.WriteAllText(output+".stderr.txt",stderr.GetAwaiter().GetResult(),Encoding.UTF8);Console.WriteLine("EXIT "+test+"="+process.ExitCode+" UTC="+DateTime.UtcNow.ToString("o"));if(process.ExitCode!=0)failed++;}}}catch(Exception e){failed++;Console.WriteLine("HARNESS FAIL "+e);}finally{try{if(owned!=null){Check(String.Equals((string)owned.FullName,file,StringComparison.OrdinalIgnoreCase),"Regression workbook identity changed");owned.Close(false);Console.WriteLine("Closed only owned regression workbook");}}catch(Exception e){failed++;Console.WriteLine("CLEANUP FAIL "+e);}try{((dynamic)originalBook).Activate();((dynamic)originalSheet).Activate();((dynamic)originalSelection).Select();app.EnableEvents=events;app.Calculation=calc;app.ScreenUpdating=screen;app.StatusBar=status;app.DisplayAlerts=alerts;Check((int)app.Workbooks.Count==prior.Count,"Existing workbook count changed");for(int i=0;i<prior.Count;i++)Check((string)((dynamic)prior[i]).FullName==names[i],"Existing workbook reference changed");Console.WriteLine("PASS original workbook references/count, selection and global states restored");}catch(Exception e){failed++;Console.WriteLine("RESTORE FAIL "+e);}foreach(object b in prior)ExcelEngine.Release(b);ExcelEngine.Release((object)owned);ExcelEngine.Release(originalSelection);ExcelEngine.Release(originalSheet);ExcelEngine.Release(originalBook);ExcelEngine.Release((object)app);}Console.WriteLine("SCOPE SUMMARY failed="+failed);return failed==0?0:1;}
}
